package dev.mechanium.api.model;
import org.bukkit.Material;
import java.util.*;
public record RecipeDefinition(String id,Type type,String resultItemId,int resultAmount,List<String> shape,Map<Character,String> ingredients,String requiredTechnologyId) {
 public enum Type { SHAPED, SHAPELESS }
 public RecipeDefinition { id=norm(id,"id");type=Objects.requireNonNull(type);resultItemId=norm(resultItemId,"resultItemId");if(resultAmount<1||resultAmount>64)throw new IllegalArgumentException("resultAmount must be 1..64");shape=shape==null?List.of():List.copyOf(shape);Map<Character,String> normalized=new TreeMap<>();if(ingredients!=null)ingredients.forEach((k,v)->{if(k==null||k==' '||k=='\\0')throw new IllegalArgumentException("Invalid ingredient key");String ingredient=Objects.requireNonNull(v).trim();if(ingredient.regionMatches(true,0,"mechanium:",0,10))ingredient="mechanium:"+norm(ingredient.substring(10),"custom ingredient");else{ingredient=ingredient.toUpperCase(Locale.ROOT);Material m=Material.matchMaterial(ingredient);if(m==null||!m.isItem())throw new IllegalArgumentException("Invalid ingredient material: "+ingredient);}normalized.put(k,ingredient);});ingredients=Map.copyOf(normalized);if(type==Type.SHAPED){if(shape.isEmpty()||shape.size()>3||shape.stream().anyMatch(row->row.isEmpty()||row.length()>3))throw new IllegalArgumentException("Shaped recipes require 1..3 rows and columns");Set<Character> used=new HashSet<>();shape.forEach(row->row.chars().filter(c->c!=' ').forEach(c->used.add((char)c)));if(!used.equals(ingredients.keySet()))throw new IllegalArgumentException("Shape and ingredient keys must match");}else if(!shape.isEmpty()||ingredients.isEmpty()||ingredients.size()>9)throw new IllegalArgumentException("Shapeless recipes need 1..9 ingredients and no shape");requiredTechnologyId=requiredTechnologyId==null||requiredTechnologyId.isBlank()?null:norm(requiredTechnologyId,"requiredTechnologyId");}
 private static String norm(String v,String f){Objects.requireNonNull(v,f);String n=v.trim().toLowerCase(Locale.ROOT);if(!n.matches("[a-z0-9][a-z0-9_.-]{1,95}"))throw new IllegalArgumentException("Invalid "+f+": "+v);return n;}
}